const localized = (value) => typeof value === 'string' ? value : value?.[lang] ?? value?.en ?? value?.nl ?? '';
const flag = (code) => /^[A-Z]{2}$/.test(code) ? String.fromCodePoint(...[...code].map(c => 127397 + c.charCodeAt(0))) : '◉';
