const navItems = [ ['overview','Overzicht','Overview'], ['network','Embassies','Embassies'], ['library','Kennisbank','Library'], ['data','Open data','Open data'], ['proposal','Het voorstel','The proposal'] ];
const categories = () => [['all','Alles','All'],['community','Community','Community'],['education','Educatie','Education'],['operations','Organisatie','Operations'],['business','Ondernemen','Business'],['governance','Beheer','Governance'],['localization','Vertalen','Translation']];
let toastTimer;
function toast(message) { $('#toast').textContent = message; $('#toast').classList.add('show'); clearTimeout(toastTimer); toastTimer = setTimeout(() => $('#toast').classList.remove('show'), 4000); }
function saveLanguage() { try {localStorage.setItem('commons-language',lang);} catch {} }
function intro(eyebrow,title,description) { return `<section class="page-intro"><div class="eyebrow">${eyebrow}</div><h1 class="page-title">${title}</h1><p>${description}</p></section>`; }
function download(content, filename, type='text/plain;charset=utf-8') { const blob = new Blob([content],{type}); const url = URL.createObjectURL(blob); const a = document.createElement('a'); a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000); }
function statusLabel(status) { return status === 'source' ? t('Openbare bron','Public source') : status === 'draft' ? t('Lokaal concept','Local draft') : t('Voorbeeldtemplate','Example template'); }
