function resourceCard(r) { return `<button class="resource-card" data-action="resource" data-id="${esc(r.id)}"><span class="category">${esc(categoryLabel(r.category))} / ${esc(r.format)}</span><h3>${esc(localized(r.title))}</h3><p>${esc(localized(r.summary))}</p><span class="resource-meta"><span>NL + EN · ${esc(r.durationMinutes)} MIN</span><span>${t('Lees & gebruik','Read & use')} ↗</span></span></button>`; }
function categoryLabel(category) { return categories().find(c => c[0] === category)?.[lang==='nl'?1:2] ?? category; }
function localHeroVisual() {return `<div class="local-emblem"><span class="flag">${flag(siteConfig.countryCode)}</span><div class="preview-logo" style="--orange:${esc(siteConfig.accent)}">₿</div><h2>${esc(siteConfig.city)}</h2><p>${esc(siteConfig.country)}</p><span class="badge">${t('Zelfstandig lokaal concept','Independent local draft')}</span><p class="micro">BUILT WITH EMBASSY COMMONS / MIT</p></div>`;}
